import org.jsoup.helper.UrlBuilder;
import org.junit.Test;
import static org.junit.Assert.*;
import java.net.URL;
import java.net.URISyntaxException;

public class UrlBuilderTest {

    @Test
    public void createUrlBuilder() {
        URL inputUrl = new URL("https://example.com/path?query=value#fragment");
        UrlBuilder builder = new UrlBuilder(inputUrl);
        assertNotNull(builder.u);
        assertNull(builder.q);
    }

    @Test
    public void build_url_is_not_punned() throws URISyntaxException {
        URL inputUrl = new URL("http://example.com/áoth?query=value#fragment");
        UrlBuilder builder = new UrlBuilder(inputUrl);
        assertEquals("http://example.com/%C3%A1oth?query=value#fragment", builder.build().toString());
    }

    @Test
    public void build_url_is_escaped() throws URISyntaxException {
        URL inputUrl = new URL("https://example.com/path?query=%3Fvalue%3D&%23fragment");
        UrlBuilder builder = new UrlBuilder(inputUrl);
        assertEquals("https://example.com/path?query=%3Fvalue=%3D&%23fragment", builder.build().toString());
    }

    @Test
    public void appendKeyVal_adds_new_key_value() throws UnsupportedEncodingException {
        URL inputUrl = new URL("https://example.com/path");
        UrlBuilder builder = new UrlBuilder(inputUrl);
        Connection.KeyVal kv = new Connection.KeyVal("key", "value");
        builder.appendKeyVal(kv);
        assertEquals("?key=value", builder.u.getQuery());
    }

    @Test
    public void appendKeyVal_adds_new_key_value_without_query() throws UnsupportedEncodingException {
        URL inputUrl = new URL("https://example.com/path?query=value");
        UrlBuilder builder = new UrlBuilder(inputUrl);
        Connection.KeyVal kv = new Connection.KeyVal("key", "value");
        builder.appendKeyVal(kv);
        assertEquals("?key=value", builder.u.getQuery());
    }

    @Test
    public void decodePart_decodes_url() throws UnsupportedEncodingException, URISyntaxException {
        String encoded = "%C3%A1oth";
        String decoded = UrlBuilder.decodePart(encoded);
        assertEquals("áoth", decoded);
    }

    @Test
    public void appendToAscii_escaped_space_as_plus() throws UnsupportedEncodingException {
        StringBuilder sb = new StringBuilder();
        UrlBuilder.appendToAscii("áóth ", true, sb);
        assertTrue(sb.toString().contains("+"));
    }

    @Test
    public void appendToAscii_escaped_non_ascii_char() throws UnsupportedEncodingException {
        StringBuilder sb = new StringBuilder();
        UrlBuilder.appendToAscii("%C3%A1oth", false, sb);
        assertEquals("%A0th", sb.toString());
    }
}
